import React, { useState, useEffect } from "react";
import styled from "styled-components";

import fetchQuery from "../components/fetchQuery";
import PageWrapper from "../components/PageWrapper";
import BookCard from "../components/BookCard";
import CardButton from "../components/CardButton";
import BookGrid from "../components/BookGrid";

// Import HOCs
import withLoadingAnimation from "../components/hoc/withLoadingAnimation";
import withImageLoading from "../components/hoc/withImageLoading";

// --- Styled Components ---

const Container = styled.div`
  margin: 20px;
  font-family: "Inter", sans-serif;
`;

const Heading = styled.h2`
  font-size: 2.5rem;
  font-weight: 800;
  background: linear-gradient(135deg, #ff416c, #ff4b2b, #ff416c);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 30px;
  text-align: center;
`;

const DropDownWrapper = styled.div`
  position: relative;
  display: inline-block;
  margin-right: 20px;
`;

const DropDownButton = styled.button`
  padding: 10px 18px;
  background: linear-gradient(135deg, #6a11cb, #2575fc);
  color: #fff;
  border: none;
  border-radius: 8px;
  font-size: 16px;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 5px;
  font-weight: 600;
  transition: all 0.3s ease;

  &:hover {
    background: linear-gradient(135deg, #2575fc, #6a11cb);
    transform: translateY(-2px);
  }
`;

const DropDownContent = styled.div`
  position: absolute;
  top: 42px;
  left: 0;
  background-color: #fff;
  border-radius: 8px;
  width: 180px;
  z-index: 3;
  display: ${(props) => (props.open ? "block" : "none")};
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.2);
`;

const DropDownItem = styled.div`
  padding: 10px;
  cursor: pointer;
  font-size: 0.95rem;
  transition: all 0.2s ease;

  &:hover {
    background-color: #f4f4f4;
  }
`;

const Input = styled.input`
  padding: 10px 14px;
  font-size: 16px;
  border: 2px solid #ccc;
  border-radius: 8px;
  width: 220px;
  margin-right: 12px;
  transition: border 0.3s ease;

  &:focus {
    outline: none;
    border-color: #ff416c;
    box-shadow: 0 0 8px rgba(255, 65, 108, 0.3);
  }
`;

const Button = styled.button`
  padding: 10px 18px;
  background: linear-gradient(135deg, #ff416c, #ff4b2b);
  color: #fff;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-size: 16px;
  font-weight: 600;
  margin-left: 10px;
  transition: all 0.3s ease;

  &:hover {
    background: linear-gradient(135deg, #ff4b2b, #ff416c);
    transform: translateY(-2px);
  }

  &:disabled {
    background: #aaa;
    cursor: not-allowed;
    transform: none;
  }
`;

const SearchWrapper = styled.div`
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  margin-bottom: 30px;
  gap: 12px;
`;

const ButtonWrapper = styled.div`
  margin-top: 8px;
  display: flex;
  justify-content: center;
`;

// --- Component ---
const AddBook = () => {
  const [criteria, setCriteria] = useState("Title");
  const [inputValue, setInputValue] = useState("");
  const [sort, setSort] = useState("Relevance");
  const [books, setBooks] = useState([]);
  const [searchDropDownOpen, setSearchDropDownOpen] = useState(false);
  const [sortDropDownOpen, setSortDropDownOpen] = useState(false);
  const [page, setPage] = useState(1);
  const [addedBooks, setAddedBooks] = useState({});
  const [loading, setLoading] = useState(false); // page-level loading

  // Responsive columns
  const [columns, setColumns] = useState(3);

  useEffect(() => {
    const calculateColumns = () => {
      const width = window.innerWidth;
      if (width > 1200) setColumns(3);
      else if (width > 900) setColumns(2);
      else setColumns(1);
    };
    calculateColumns();
    window.addEventListener("resize", calculateColumns);
    return () => window.removeEventListener("resize", calculateColumns);
  }, []);

  const maxRows = 7; // 3 cols * 7 rows = 21 books max
  const pageSize = Math.min(columns * maxRows, 21);

  const handleSearch = async () => {
    setBooks([]);
    setLoading(true);
    const result = await fetchQuery(null, criteria, inputValue, sort);
    setBooks(result || []);
    setLoading(false);
  };

  const addtoLib = (book) => {
    if (addedBooks[book.title]) return;

    setAddedBooks((prevState) => ({
      ...prevState,
      [book.title]: true,
    }));

    let myBooks = JSON.parse(localStorage.getItem("books")) || {};
    myBooks[book.title] = book;
    localStorage.setItem("books", JSON.stringify(myBooks));
  };

  const toggleSearchDropDown = () => {
    setSearchDropDownOpen(!searchDropDownOpen);
    setSortDropDownOpen(false);
  };
  const toggleSortDropDown = () => {
    setSortDropDownOpen(!sortDropDownOpen);
    setSearchDropDownOpen(false);
  };

  const handleSearchDropDownItemClick = (newCriteria) => {
    setCriteria(newCriteria);
    setSearchDropDownOpen(false);
  };
  const handleSortDropDownItemClick = (newSort) => {
    setSort(newSort);
    setSortDropDownOpen(false);
  };

  // Wrap BookCard image with loading HOC
  const BookCardWithImageLoading = (props) => {
    const ImageWithLoading = withImageLoading(({ src, alt }) => (
      <img src={src} alt={alt} style={{ width: "100%", height: "auto" }} />
    ));
    return <BookCard {...props} ImageComponent={ImageWithLoading} />;
  };

  // Wrap BookGrid for page-level loading
  const BookGridWithLoading = withLoadingAnimation(BookGrid);

  const totalPages = Math.ceil(Math.min(books.length, 21) / pageSize);

  return (
    <PageWrapper>
      <Container>
        <Heading>Discover Your Next Read 📚</Heading>

        <SearchWrapper>
          <DropDownWrapper>
            <DropDownButton onClick={toggleSearchDropDown}>
              Search By: {criteria}
            </DropDownButton>
            <DropDownContent open={searchDropDownOpen}>
              <DropDownItem onClick={() => handleSearchDropDownItemClick("Title")}>Title</DropDownItem>
              <DropDownItem onClick={() => handleSearchDropDownItemClick("Author")}>Author</DropDownItem>
              <DropDownItem onClick={() => handleSearchDropDownItemClick("ISBN")}>ISBN</DropDownItem>
            </DropDownContent>
          </DropDownWrapper>

          <DropDownWrapper>
            <DropDownButton onClick={toggleSortDropDown}>
              Sort By: {sort}
            </DropDownButton>
            <DropDownContent open={sortDropDownOpen}>
              <DropDownItem onClick={() => handleSortDropDownItemClick("Relevance")}>Relevance</DropDownItem>
              <DropDownItem onClick={() => handleSortDropDownItemClick("Newest")}>Newest</DropDownItem>
              <DropDownItem onClick={() => handleSortDropDownItemClick("Rating")}>Rating</DropDownItem>
            </DropDownContent>
          </DropDownWrapper>

          <Input
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            placeholder={`Enter ${criteria}`}
          />

          <Button onClick={handleSearch}>Search</Button>
        </SearchWrapper>

        {/* --- GRID --- */}
        <BookGridWithLoading loading={loading}>
          {books.length > 0 &&
            books.slice((page - 1) * pageSize, page * pageSize).map((book) => (
              <div key={book.isbn}>
                <BookCardWithImageLoading {...book} />
                <ButtonWrapper>
                  <CardButton variant="add" onClick={() => addtoLib(book)}>
                    {addedBooks[book.title] ? "Added! Enjoy Reading!" : "Add to Library"}
                  </CardButton>
                </ButtonWrapper>
              </div>
            ))}
        </BookGridWithLoading>

        {/* --- Pagination --- */}
        {books.length > 0 && totalPages > 1 && (
          <div style={{ display: "flex", justifyContent: "center", marginTop: "30px", flexWrap: "wrap", gap: "8px" }}>
            {page > 1 && <Button onClick={() => setPage(page - 1)}>{"<"}</Button>}

            {Array.from({ length: totalPages }, (_, index) => (
              <Button
                key={index}
                onClick={() => setPage(index + 1)}
                disabled={page === index + 1}
              >
                {index + 1}
              </Button>
            ))}

            {page < totalPages && <Button onClick={() => setPage(page + 1)}>{">"}</Button>}
          </div>
        )}
      </Container>
    </PageWrapper>
  );
};

export default AddBook;
